```sysml
package T {
    private import SI::*;
    port def Pw { attribute voltage :> ISQ::voltage; }
    interface def L { end a : Pw; end b : ~Pw; bind a.voltage = b.voltage; }
    part def Src { port src : Pw { attribute :>> voltage = 28 [V]; } }
    part def Snk { port dst : ~Pw; }
    part def Y {
        part s : Src;
        part k : Snk;
        interface i : L connect s.src to k.dst;
        assert constraint c { k.dst.voltage == 28 [V] }
